function copyPrev(d){const p=S.daily[addD(d,-1)];if(!p)return;const r=dr(d);r.symptoms=[...p.symptoms];r.sev=p.sev?{...p.sev}:undefined;if(p.mood)r.mood=p.mood;if(p.pain)r.pain=p.pain;save();dayS(d);render();toast('Copied from the day before. Edit anything that differs.')}
