function pastDay(){const days=[...Array(7)].map((_,i)=>addD(today(),-i)),lg=d=>{const r=S.daily[d];return r&&(r.symptoms.length||r.mood||r.pain||r.notes||r.flow||r.spot)};sheet(`<h3>Log a different date</h3><p>Tap a day from the past week, or choose any earlier date.</p><div>${days.map(d=>`<button class="ch ${lg(d)?'s':''}" onclick="dayS('${d}')">${fs(d,{weekday:'short',day:'numeric'})}${lg(d)?' ✓':''}</button>`).join('')}</div><label>Any earlier date</label><input type="date" id="pd" max="${today()}" value="${addD(today(),-8)}"><button class="b" onclick="const v=document.getElementById('pd').value;if(!v||isNaN(s2d(v))||v>today())return toast('Choose today or an earlier date.');dayS(v)">Open this day</button>`)}
const _sd=sumData;sumData=function(){const a=_sd(),ds=Object.values(S.daily),c=cy(),sv={};ds.forEach(r=>r.symptoms.forEach(x=>{const k=x+(r.sev&&r.sev[x]?' ('+r.sev[x]+')':'');sv[k]=(sv[k]||0)+1}));
const bd=ds.filter(r=>r.flow).length,sp=ds.filter(r=>r.spot).length,cl=ds.filter(r=>r.clots).length,hv=ds.filter(r=>r.flow==='Heavy').length,sevP=ds.filter(r=>r.pain==='Severe').length,out=c.lens.filter(l=>l<21||l>35).length,lp=S.periods.filter(p=>p.endDate&&diff(p.startDate,p.endDate)+1>7).length;
const pts=[];if(out)pts.push(out+' of '+c.lens.length+' logged cycles were shorter than 21 or longer than 35 days.');if(lp)pts.push(lp+' logged period(s) lasted longer than 7 days.');if(hv)pts.push('Heavy flow was logged on '+hv+' day(s).');if(cl)pts.push('Clots were logged on '+cl+' day(s).');if(sevP)pts.push('Severe pain was logged on '+sevP+' day(s).');
const ex=[['Symptoms with severity (days)',Object.keys(sv).length?Object.entries(sv).sort((x,y)=>y[1]-x[1]).slice(0,12).map(x=>x[0]+': '+x[1]):['None logged.']],['Bleeding days logged',['Days with flow recorded: '+bd,'Spotting days: '+sp,'Days with clots noted: '+cl]],['Points that may be worth discussing',pts.length?pts.concat(['These are observations from your own log, not a diagnosis.']):['Nothing in your log crossed these simple checks. Discuss any concerns regardless.']]];a.splice(a.length-1,0,...ex);return a};
