async function encGo(){const p=document.getElementById('xp').value;if(p.length<6)return toast('Use at least 6 characters.');try{const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),k=await kdf(p,salt),ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,new TextEncoder().encode(JSON.stringify(S)));dl('health-tracker-backup.encrypted.json',JSON.stringify({enc:1,salt:b64(salt),iv:b64(iv),data:b64(ct)}),'application/json');S.lastBackup=Date.now();save();shut();toast('Encrypted backup downloaded.')}catch(e){toast('Encryption is not available in this browser.')}}
const okDate=d=>typeof d==='string'&&/^\d{4}-\d\d-\d\d$/.test(d)&&!isNaN(s2d(d));
function applyImport(d){if(!d||typeof d.set!=='object'||!Array.isArray(d.periods)||typeof d.daily!=='object'||d.daily===null)throw 0;d.periods=d.periods.filter(p=>p&&okDate(p.startDate)&&(!p.endDate||(okDate(p.endDate)&&p.endDate>=p.startDate)));Object.keys(d.daily).forEach(k=>{if(!okDate(k)||typeof d.daily[k]!=='object'||!Array.isArray(d.daily[k].symptoms))delete d.daily[k]});S=Object.assign(JSON.parse(JSON.stringify(DEF)),d);S.set=Object.assign({},DEF.set,d.set);S.preg=S.preg||{on:false,lmp:'',notes:[]};S.rem=S.rem||[];S.v3=1;save();hist=[];go('home');toast('Data restored on this device.')}
function imp(el){const f=el.files[0];if(!f)return;if(f.size>5e6)return toast('That file is too large.');const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(d.enc){window._enc=d;return sheet('<h3>Encrypted backup</h3><p>Enter the passphrase you chose.</p><input id="xp" type="password" autocomplete="current-password"><button class="b" onclick="decGo()">Restore</button><button class="b g" onclick="shut()">Cancel</button>')}applyImport(d)}catch(e){toast('That file is not a valid backup.')}};r.readAsText(f)}
async function decGo(){try{const d=window._enc,k=await kdf(document.getElementById('xp').value,ub(d.salt)),pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:ub(d.iv)},k,ub(d.data));shut();applyImport(JSON.parse(new TextDecoder().decode(pt)))}catch(e){toast('Wrong passphrase or damaged file.')}}
SUB.data=()=>hd('Data management')+`<div class="c"><h3>Where your data lives</h3><p>Only in this browser on this device. There is no account, no cloud copy and no server, so nobody else can restore it for you. To move to a new phone, save a backup here and import it there.</p></div><div class="c"><button class="b o" style="margin:0" onclick="exp()">Backup file (not encrypted)</button><button class="b" onclick="encAsk()">Encrypted backup (recommended)</button><p style="margin-top:6px">${S.lastBackup?'Last backup: '+new Date(S.lastBackup).toLocaleDateString():'No backup yet.'}</p><label>Restore from a backup file</label><input type="file" id="imp" accept="application/json,.json" onchange="imp(this)"><button class="b d" onclick="sheet('<h3>Delete all health data?</h3><p>Every period, log, journal entry and setting will be removed from this device.</p><button class=\\'b\\' onclick=\\'del2()\\'>Continue</button><button class=\\'b g\\' onclick=\\'shut()\\'>Cancel</button>')">Delete all data</button></div>`;
const _pv=SUB.priv;SUB.priv=()=>_pv()+`<div class="c"><h3>Privacy check</h3><p>Stored: your logs, journal, settings and PIN check value, in this browser only.</p><p>Not used: accounts, servers, analytics, ads, cookies, location or external fonts and scripts. A security policy in the page blocks network requests.</p><p>Limits: data in the browser is not encrypted, and the PIN only hides the screen. Anyone who can open this browser profile could read the data. Use a device passcode, and use the encrypted backup for files.</p></div>`;
if(S.ob<99){cur='ob'}else if(S.set.pin){cur='lock'}
render();

/* ---- install / offline info ---- */
const APP_VERSION='1.0.0';
function installApp(){const e=window._installEvt;if(!e)return toast('Install is not available right now.');e.prompt();e.userChoice.finally(()=>{window._installEvt=null;render()})}
const _ab=SUB.about;SUB.about=()=>_ab()+(window._installEvt?'<button class="b" onclick="installApp()">Install app</button>':'')+`<div class="c"><h3>Offline &amp; install</h3><p>After the first load, every screen works without internet. Your data never leaves this device.</p><p>Version ${APP_VERSION}</p></div>`;
